static void aw_Capacitor_process_fast(void *aw_state, int16_t *aw_out,
    const int16_t *aw_in, int32_t sampleFrames, uint32_t aw_channels) {
    aw_Capacitor_fast_t *aw_s = (aw_Capacitor_fast_t *)aw_state;
    const double aw_sample_rate = aw_s->aw_sample_rate;
    (void)aw_sample_rate;
    float iirHighpassAL = aw_s->iirHighpassAL;
    float iirHighpassBL = aw_s->iirHighpassBL;
    float iirHighpassCL = aw_s->iirHighpassCL;
    float iirHighpassDL = aw_s->iirHighpassDL;
    float iirHighpassEL = aw_s->iirHighpassEL;
    float iirHighpassFL = aw_s->iirHighpassFL;
    float iirLowpassAL = aw_s->iirLowpassAL;
    float iirLowpassBL = aw_s->iirLowpassBL;
    float iirLowpassCL = aw_s->iirLowpassCL;
    float iirLowpassDL = aw_s->iirLowpassDL;
    float iirLowpassEL = aw_s->iirLowpassEL;
    float iirLowpassFL = aw_s->iirLowpassFL;
    float iirHighpassAR = aw_s->iirHighpassAR;
    float iirHighpassBR = aw_s->iirHighpassBR;
    float iirHighpassCR = aw_s->iirHighpassCR;
    float iirHighpassDR = aw_s->iirHighpassDR;
    float iirHighpassER = aw_s->iirHighpassER;
    float iirHighpassFR = aw_s->iirHighpassFR;
    float iirLowpassAR = aw_s->iirLowpassAR;
    float iirLowpassBR = aw_s->iirLowpassBR;
    float iirLowpassCR = aw_s->iirLowpassCR;
    float iirLowpassDR = aw_s->iirLowpassDR;
    float iirLowpassER = aw_s->iirLowpassER;
    float iirLowpassFR = aw_s->iirLowpassFR;
    int count = aw_s->count;
    float lowpassChase = aw_s->lowpassChase;
    float highpassChase = aw_s->highpassChase;
    float wetChase = aw_s->wetChase;
    float lowpassAmount = aw_s->lowpassAmount;
    float highpassAmount = aw_s->highpassAmount;
    float wet = aw_s->wet;
    float lastLowpass = aw_s->lastLowpass;
    float lastHighpass = aw_s->lastHighpass;
    float lastWet = aw_s->lastWet;
    uint32_t fpdL = aw_s->fpdL;
    uint32_t fpdR = aw_s->fpdR;
    float A = aw_s->A;
    float B = aw_s->B;
    float C = aw_s->C;
    {
	
	lowpassChase = pow(A,2);
	highpassChase = pow(B,2);
	wetChase = C;
	//should not scale with sample rate, because values reaching 1 are important
	//to its ability to bypass when set to max
	double lowpassSpeed = 300 / (fabs( lastLowpass - lowpassChase)+1.0);
	double highpassSpeed = 300 / (fabs( lastHighpass - highpassChase)+1.0);
	double wetSpeed = 300 / (fabs( lastWet - wetChase)+1.0);
	lastLowpass = lowpassChase;
	lastHighpass = highpassChase;
	lastWet = wetChase;
	
	float invLowpass;
	float invHighpass;
	float dry;
	

	float inputSampleL;
	float inputSampleR;
	float drySampleL;
	float drySampleR;
	    
    const float aw_f_lowpassSpeed = (float)lowpassSpeed;
	const float aw_f_highpassSpeed = (float)highpassSpeed;
	const float aw_f_wetSpeed = (float)wetSpeed;
	const float aw_inv0 = 1.0f / ((aw_f_lowpassSpeed + 1.0f));
	const float aw_inv1 = 1.0f / ((aw_f_highpassSpeed + 1.0f));
	const float aw_inv2 = 1.0f / ((aw_f_wetSpeed+1.0f));
	while (--sampleFrames >= 0)
    {
		const float aw_inL = AW_IN_L(aw_in);
		const float aw_inR = AW_IN_R(aw_in, aw_channels);
		float aw_outL = 0.0f, aw_outR = 0.0f;/* aw:loop */
		inputSampleL = aw_inL;
		inputSampleR = aw_inR;
		if (fabsf(inputSampleL)<1.18e-23f) inputSampleL = fpdL * 1.18e-17f;
		if (fabsf(inputSampleR)<1.18e-23f) inputSampleR = fpdR * 1.18e-17f;
		drySampleL = inputSampleL;
		drySampleR = inputSampleR;


		lowpassAmount = (((lowpassAmount*aw_f_lowpassSpeed)+lowpassChase)* aw_inv0); invLowpass = 1.0f - lowpassAmount;
		highpassAmount = (((highpassAmount*aw_f_highpassSpeed)+highpassChase)* aw_inv1); invHighpass = 1.0f - highpassAmount;
		wet = (((wet*aw_f_wetSpeed)+wetChase)* aw_inv2); dry = 1.0f - wet;
		
		count++; if (count > 5) count = 0; switch (count)
		{
			case 0:
				iirHighpassAL = (iirHighpassAL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassAL;
				iirHighpassBL = (iirHighpassBL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassBL;
				iirLowpassBL = (iirLowpassBL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassBL;
				iirHighpassDL = (iirHighpassDL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassDL;
				iirLowpassDL = (iirLowpassDL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassDL;
				iirHighpassAR = (iirHighpassAR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassAR;
				iirHighpassBR = (iirHighpassBR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassBR;
				iirLowpassBR = (iirLowpassBR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassBR;
				iirHighpassDR = (iirHighpassDR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassDR;
				iirLowpassDR = (iirLowpassDR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassDR;
				break;
			case 1:
				iirHighpassAL = (iirHighpassAL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassAL;
				iirHighpassCL = (iirHighpassCL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassCL;
				iirLowpassCL = (iirLowpassCL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassCL;
				iirHighpassEL = (iirHighpassEL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassEL;
				iirLowpassEL = (iirLowpassEL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassEL;
				iirHighpassAR = (iirHighpassAR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassAR;
				iirHighpassCR = (iirHighpassCR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassCR;
				iirLowpassCR = (iirLowpassCR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassCR;
				iirHighpassER = (iirHighpassER * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassER;
				iirLowpassER = (iirLowpassER * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassER;
				break;
			case 2:
				iirHighpassAL = (iirHighpassAL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassAL;
				iirHighpassBL = (iirHighpassBL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassBL;
				iirLowpassBL = (iirLowpassBL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassBL;
				iirHighpassFL = (iirHighpassFL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassFL;
				iirLowpassFL = (iirLowpassFL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassFL;
				iirHighpassAR = (iirHighpassAR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassAR;
				iirHighpassBR = (iirHighpassBR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassBR;
				iirLowpassBR = (iirLowpassBR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassBR;
				iirHighpassFR = (iirHighpassFR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassFR;
				iirLowpassFR = (iirLowpassFR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassFR;
				break;
			case 3:
				iirHighpassAL = (iirHighpassAL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassAL;
				iirHighpassCL = (iirHighpassCL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassCL;
				iirLowpassCL = (iirLowpassCL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassCL;
				iirHighpassDL = (iirHighpassDL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassDL;
				iirLowpassDL = (iirLowpassDL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassDL;
				iirHighpassAR = (iirHighpassAR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassAR;
				iirHighpassCR = (iirHighpassCR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassCR;
				iirLowpassCR = (iirLowpassCR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassCR;
				iirHighpassDR = (iirHighpassDR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassDR;
				iirLowpassDR = (iirLowpassDR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassDR;
				break;
			case 4:
				iirHighpassAL = (iirHighpassAL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassAL;
				iirHighpassBL = (iirHighpassBL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassBL;
				iirLowpassBL = (iirLowpassBL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassBL;
				iirHighpassEL = (iirHighpassEL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassEL;
				iirLowpassEL = (iirLowpassEL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassEL;
				iirHighpassAR = (iirHighpassAR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassAR;
				iirHighpassBR = (iirHighpassBR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassBR;
				iirLowpassBR = (iirLowpassBR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassBR;
				iirHighpassER = (iirHighpassER * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassER;
				iirLowpassER = (iirLowpassER * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassER;
				break;
			case 5:
				iirHighpassAL = (iirHighpassAL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassAL;
				iirHighpassCL = (iirHighpassCL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassCL;
				iirLowpassCL = (iirLowpassCL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassCL;
				iirHighpassFL = (iirHighpassFL * invHighpass) + (inputSampleL * highpassAmount); inputSampleL -= iirHighpassFL;
				iirLowpassFL = (iirLowpassFL * invLowpass) + (inputSampleL * lowpassAmount); inputSampleL = iirLowpassFL;
				iirHighpassAR = (iirHighpassAR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassAR;
				iirHighpassCR = (iirHighpassCR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassCR;
				iirLowpassCR = (iirLowpassCR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassCR;
				iirHighpassFR = (iirHighpassFR * invHighpass) + (inputSampleR * highpassAmount); inputSampleR -= iirHighpassFR;
				iirLowpassFR = (iirLowpassFR * invLowpass) + (inputSampleR * lowpassAmount); inputSampleR = iirLowpassFR;
				break;
		}
		//Highpass Filter chunk. This is three poles of IIR highpass, with a 'gearbox' that progressively
		//steepens the filter after minimizing artifacts.
		
		inputSampleL = (drySampleL * dry) + (inputSampleL * wet);
		inputSampleR = (drySampleR * dry) + (inputSampleR * wet);
		fpdL ^= fpdL << 13; fpdL ^= fpdL >> 17; fpdL ^= fpdL << 5;
		fpdR ^= fpdR << 13; fpdR ^= fpdR >> 17; fpdR ^= fpdR << 5;
		//end 32 bit stereo floating point dither

		aw_outL = inputSampleL;
		aw_outR = inputSampleR;
    /* aw:end */		AW_OUT_FAST(aw_out, aw_channels, aw_outL, aw_outR);
		aw_in += aw_channels;
		aw_out += aw_channels;
	}
}
    aw_s->iirHighpassAL = iirHighpassAL;
    aw_s->iirHighpassBL = iirHighpassBL;
    aw_s->iirHighpassCL = iirHighpassCL;
    aw_s->iirHighpassDL = iirHighpassDL;
    aw_s->iirHighpassEL = iirHighpassEL;
    aw_s->iirHighpassFL = iirHighpassFL;
    aw_s->iirLowpassAL = iirLowpassAL;
    aw_s->iirLowpassBL = iirLowpassBL;
    aw_s->iirLowpassCL = iirLowpassCL;
    aw_s->iirLowpassDL = iirLowpassDL;
    aw_s->iirLowpassEL = iirLowpassEL;
    aw_s->iirLowpassFL = iirLowpassFL;
    aw_s->iirHighpassAR = iirHighpassAR;
    aw_s->iirHighpassBR = iirHighpassBR;
    aw_s->iirHighpassCR = iirHighpassCR;
    aw_s->iirHighpassDR = iirHighpassDR;
    aw_s->iirHighpassER = iirHighpassER;
    aw_s->iirHighpassFR = iirHighpassFR;
    aw_s->iirLowpassAR = iirLowpassAR;
    aw_s->iirLowpassBR = iirLowpassBR;
    aw_s->iirLowpassCR = iirLowpassCR;
    aw_s->iirLowpassDR = iirLowpassDR;
    aw_s->iirLowpassER = iirLowpassER;
    aw_s->iirLowpassFR = iirLowpassFR;
    aw_s->count = count;
    aw_s->lowpassChase = lowpassChase;
    aw_s->highpassChase = highpassChase;
    aw_s->wetChase = wetChase;
    aw_s->lowpassAmount = lowpassAmount;
    aw_s->highpassAmount = highpassAmount;
    aw_s->wet = wet;
    aw_s->lastLowpass = lastLowpass;
    aw_s->lastHighpass = lastHighpass;
    aw_s->lastWet = lastWet;
    aw_s->fpdL = fpdL;
    aw_s->fpdR = fpdR;
}

static const uint32_t aw_Capacitor_offsets_fast[] = {offsetof(aw_Capacitor_fast_t, A), offsetof(aw_Capacitor_fast_t, B), offsetof(aw_Capacitor_fast_t, C)};
#endif

